은 전체 유권자 대상 조사 결과를 가공 없이 인용한 것”이라고 반박했다. 이어 “판단은 선관위가 할 사안”이라고 밝혔다. 더불어민주당 남궁형 제물포구청장 예비후보가 올린 여론조사 그래픽 여론조사 요약 의뢰·조사기관: 인천투데이 의뢰 / 데일리리서치 조사기간: 3월 19일~20일 (2일간) 조사대상: 인천 중구(제1선거구)·동구 거주 만 18세 이상 남녀 501명 조사방법: 유무선 ARS 전화조사 휴대전화 가상번호 94% 유선전화 RDD 6% 응답률: 5.3% 표본오차: ±4.4%p (95% 신뢰수준) 자세한 내용은 중앙선거여론조사심의위원회 홈페이지 $(function() { const copyUrlOptions=document.querySelectorAll(".urlBtns, .sns_clipboard"); // 주소복사 이벤트 (v11-fl-v2 수정) copyUrlOptions.forEach(selector=>{ selector.addEventListener("click", (e)=>{ const target=e.target, targetBtn=target.closest("[data-clipboard-text]"); if (targetBtn===null) return; const url=targetBtn.getAttribute("data-clipboard-text")||""; Util.copyToClipboardToast(selector, '', url); }); }); // 사진 lightBox 이벤트 if (typeof ImageViewer != "undefined") { new ImageViewer(".photo-layout", 0); } }); // PC $(document).ready(function() { articleStrongEffect.eventStart(0); }); $(function() { // information group $(".information-container").on("click", ".info-update", function(e) { const _this = $(e.currentTarget); if(_this.hasClass("show")) { _this.removeClass("show"); } else { _this.addClass("show"); } }); // scrap button $('.helper-tool-group').on('click', '.page-scrap', function(e) { var idxno = $(this).data('idxno'); if(confirm("기사를 스크랩 하시겠습니까?")){ $.ajax({ type: 'post', dataType: 'json', url: '/news/articleScrap.ajax.php', data: {'tp':'A', 'idxno':idxno}, success: function(data) { alert(data[1]); }, error: function(error, request) { alert('error!!!'); console.log("code:"+request.status+"\n"+"message:"+request.responseText+"\n"+"error:"+error); } }); } }); }); 이 기사를 공유합니다 관련기사 [기획]인천 선거-②지방선거 앞두고 ‘전과 논란’ 재점화…공천 갈등 격화
