.view_S1N13_top span{color:#2980b9;} @media screen and (max-width: 39.9375em) { } 이병래 예비후보(좌)와 김성수 예비후보(우)가 손을 맞잡고 만세를 하고 있다 / 사진제공=이병래 남동구청장 후보 캠프 더불어민주당 남동구청장 경선에 나섰던 김성수 예비후보가 결과에 승복하고 이병래 후보 지지를 선언하며 선거 구도가 단일대오로 재편됐다. 21일 정치권에 따르면 김성수 후보는 이병래 후보와 정책협약을 맺고 결선과 본선을 함께 치르겠다는 입장을 밝혔다. 자신이 제안한 정책을 이병래 후보가 주요 과제로 수용하기로 하면서 공동 행보에 나섰다. 두 후보는 생활체육과 소래포구 관련 정책을 중심으로 협력을 이어가기로 했다. 경선 과정에서 제시된 정책이라도 지역에 필요하다면 이어져야 한다는 인식이 반영된 합의다. 이병래 후보는 생활체육과 지역경제를 연계한 체류형 스포츠 모델을 추진하고, 남동경기장 등 공공체육시설을 문화와 상권이 결합된 공간으로 활용하겠다는 계획을 밝혔다. 소래포구에 대해서는 관광 콘텐츠 확충과 서비스 개선을 통해 지역 대표 관광 거점으로 육성하겠다는 방침이다. 김성수 후보는 경선 결과를 수용하며 정책 실현을 위한 협력 의지를 강조했다. 김성수 후보는 “경선 결과에 승복한다”며 “정치는 경쟁으로 끝나는 것이 아니라 구민의 삶을 바꾸는 실천으로 이어져야 한다고 생각한다. 제가 제안한 정책이 이병래 후보를 통해 실제 남동구의 변화로 이어질 수 있도록 뜻을 모았다”고 말했다. 이어 “남동구의 변화와 민주당 승리를 위해 이병래 후보와 원팀으로 결선과 본선을 함께 치르며 끝까지 힘을 보태겠다”고 밝혔다. 이병래 후보는 “김성수 후보가 제안한 생활체육과 소래포구 관련 정책은 남동구 지역경제 활성화와 주민 삶의 질 향상에 중요한 의미를 갖는다”며 “정책협약을 통해 그 취지와 문제의식을 존중해 수용한 만큼, 남동구의 주요 실천 과제로 반영해 책임 있게 추진하겠다”고 말했다. 이어 “김성수 후보의 정책 제안을 이어받아 원팀의 힘으로 선거에서 승리하겠다”고 밝혔다. 양측은 이번 협약이 정책을 공유하고 선거 경쟁력을 높이기 위한 출발점이라는 데 의견을 같이했다. 남동구 정책 방향을 함께 추진하며 선거 과정에서도 공동 대응을 이어갈 계획이다. $(function() { const copyUrlOptions=document.querySelectorAll(".urlBtns, .sns_clipboard"); // 주소복사 이벤트 (v11-fl-v2 수정) copyUrlOptions.forEach(selector=>{ selector.addEventListener("click", (e)=>{ const target=e.target, targetBtn=target.closest("[data-clipboard-text]"); if (targetBtn===null) return; const url=targetBtn.getAttribute("data-clipboard-text")||""; Util.copyToClipboardToast(selector, '', url); }); }); // 사진 lightBox 이벤트 if (typeof ImageViewer != "undefined") { new ImageViewer(".photo-layout", 0); } }); 김정호 기자 kjh6114@kmaeil.com 다른기사 보기 저작권자 © 경인매일 무단전재 및 재배포, AI학습 및 활용 금지 개의 댓글 회원로그인 작성자 비밀번호 댓글 내용입력 0 / 400 등록 댓글 정렬 최신순 추천순 답글순 BEST댓글 BEST 댓글 답글과 추천수를 합산하여 자동으로 노출됩니다. 닫기 더보기 댓글삭제 삭제한 댓글은 다시 복구할 수 없습니다. 그래도 삭제하시겠습니까? 비밀번호 삭제 댓글수정 댓글 수정은 작성 후 1분내에만 가능합니다. 본문 / 400 비밀번호 수정 내 댓글 모음 닫기 $comment.service_code = 'news'; // 현재 이용 서비스 (중요!!)
